class OrderStateMachine:
    STATES = {'created', 'paid', 'shipped', 'delivered', 'cancelled', 'refunded'}

    TRANSITIONS = {
        'created': {'paid', 'cancelled'},
        'paid': {'shipped', 'refunded'},
        'shipped': {'delivered', 'cancelled'},
        'delivered': {'refunded'},
        'cancelled': set(),
        'refunded': set(),
    }

    def __init__(self):
        self.state = 'created'

    def transition(self, new_state):
        if new_state not in self.STATES:
            raise ValueError(f"Unknown state: {new_state}")
        if new_state not in self.TRANSITIONS[self.state]:
            raise ValueError(
                f"Cannot transition {self.state} → {new_state}. "
                f"Valid: {self.TRANSITIONS[self.state] or 'none (terminal)'}"
            )
        self.state = new_state
        return self.state

    def can_transition(self, new_state):
        return new_state in self.TRANSITIONS.get(self.state, set())


# Usage
if __name__ == '__main__':
    order = OrderStateMachine()

    print(f"Initial: {order.state}")
    order.transition('paid')
    print(f"After payment: {order.state}")
    order.transition('shipped')
    print(f"After shipment: {order.state}")
    order.transition('delivered')
    print(f"After delivery: {order.state}")

    try:
        order.transition('paid')  # Invalid: delivered → paid
    except ValueError as e:
        print(f"❌ {e}")

    order.transition('refunded')
    print(f"After refund: {order.state}")

    try:
        order.transition('shipped')  # Invalid: refunded is terminal
    except ValueError as e:
        print(f"❌ {e}")
```

Valid transitions:
- `created` → paid, cancelled
- `paid` → shipped, refunded
- `shipped` → delivered, cancelled
- `delivered` → refunded
- `cancelled`, `refunded` → terminal (no exits)

Invalid transitions raise `ValueError` with allowed alternatives. `can_transition()` checks without throwing.
